elements/headline/element.css.text:
/* Replica 11: A full accent band reproduces replica11 with a left-aligned22px statement and a small dark round control at the right edge.
   Newly authored ratios; no page selectors or prior stylesheet layers. */
.headline[data-el="dockside-headline"]{position:relative;min-width:0;min-height:0;container-type:size;color:var(--ink);font-family:var(--font-body);font-weight:var(--body-weight);font-size:var(--type-16);line-height:var(--body-line);letter-spacing:var(--body-track)}
.headline[data-el="dockside-headline"] *{box-sizing:border-box;min-width:0}
.headline[data-el="dockside-headline"]{width:100%;height:100%;max-width:604px;max-height:200px;align-self:center;justify-self:center;display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);padding:var(--pad) calc(var(--pad)*1.35);border-radius:var(--radius-sm);background:var(--a1);color:var(--a1-on);box-shadow:0 6px 14px var(--a1-2-soft)}
.headline[data-el="dockside-headline"]>h2{position:relative;margin:0;padding-right:16%;font-size:clamp(var(--type-14),3.65cqw,var(--type-22));font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}
.headline[data-el="dockside-headline"]>h2>b{font-weight:var(--title-weight)}.headline[data-el="dockside-headline"]>h2>.icon{position:absolute;right:0;top:50%;transform:translateY(-50%);display:block;width:min(7cqw,37px);height:min(7cqw,37px);padding:calc(var(--gap-sm)*.75);border-radius:50%;background:var(--ink);color:var(--page);box-shadow:0 4px 8px var(--n-2)}
.headline[data-el="dockside-headline"]>.kick{margin:0;font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line)}.headline[data-el="dockside-headline"]>.note{margin:0;font-size:var(--type-16);line-height:var(--body-line);color:inherit}
.headline[data-el="dockside-headline"].center{text-align:center;align-items:center}.headline[data-el="dockside-headline"].center>h2{padding-right:0}.headline[data-el="dockside-headline"].big>h2{font-size:clamp(var(--type-24),5cqw,var(--type-52));line-height:var(--title-line)}.headline[data-el="dockside-headline"].on{background:var(--a1-7);color:var(--page)}
.headline[data-el="dockside-headline"]:not(:has(>.kick)):not(:has(>.note)){max-height:78px}
@container(max-height:100px){.headline[data-el="dockside-headline"]>.kick{display:none}.headline[data-el="dockside-headline"]>.note{display:none}}@container(max-width:400px){.headline[data-el="dockside-headline"]>h2{font-size:var(--type-18)}.headline[data-el="dockside-headline"].big>h2{font-size:var(--type-28)}}

elements/prose/element.css.text:
/* Replica 08: Measured16px muted running copy is vertically balanced inside its slot.
   Newly authored ratios; no page selectors or prior stylesheet layers. */
.prose[data-el="dockside-prose"]{position:relative;min-width:0;min-height:0;container-type:size;color:var(--ink);font-family:var(--font-body);font-weight:var(--body-weight);font-size:var(--type-16);line-height:var(--body-line);letter-spacing:var(--body-track)}
.prose[data-el="dockside-prose"] *{box-sizing:border-box;min-width:0}
.prose[data-el="dockside-prose"]{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);padding:0}
.prose[data-el="dockside-prose"]>p{margin:0;font-size:var(--type-16);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7);overflow-wrap:anywhere}
.prose[data-el="dockside-prose"]>p>b{font-weight:var(--name-weight);color:var(--ink)}
.prose[data-el="dockside-prose"].quiet>p{font-size:var(--type-14)}.prose[data-el="dockside-prose"].lead>p{font-size:var(--type-24);line-height:var(--lead-line)}.prose[data-el="dockside-prose"].lead>p>b{color:var(--a1-7)}
.prose[data-el="dockside-prose"].cols{display:block;column-count:2;column-gap:var(--gap-lg);align-content:center}.prose[data-el="dockside-prose"].cols>p{break-inside:avoid;margin-bottom:var(--gap)}
@container(max-width:450px){.prose[data-el="dockside-prose"]>p{font-size:var(--type-14)}.prose[data-el="dockside-prose"].lead>p{font-size:var(--type-20)}.prose[data-el="dockside-prose"].cols{column-count:1}}
@container(max-height:150px){.prose[data-el="dockside-prose"]>p{font-size:var(--type-12)}.prose[data-el="dockside-prose"].lead>p{font-size:var(--type-18)}}
